import java.util.Scanner;

public class Main {
    static long n_input;
    static int min_cost = Integer.MAX_VALUE;

    static void search_path(long n, int c) {
        if (c >= min_cost) return;
        if (n == 0) {
            min_cost = c;
            return;
        }
        long s = 1;
        int c_count = 1;
        while (s * 10 + 1 <= n) {
            s = s * 10 + 1;
            c_count++;
        }
        search_path(n % s, c + c_count * (int)(n / s));
        search_path(s * 10 + 1 - n, c + 1 + c_count);
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        n_input = sc.nextLong();
        sc.close();
        search_path(n_input, 0);
        System.out.println(min_cost);
    }
}
